// HM-PF-53 shared GATE-UX notify template (same text as HM UI "Copy notify").
// Control + notify only: no HTTP, no compose/save, no .motion.json write.
const g = $input.first().json;
const show = g.show_id || '{show_id}';
const resume = $execution.resumeFormUrl || '{resumeFormUrl}';
const link = `${g.hm_origin}/ui/?show=${encodeURIComponent(show)}#${g.hm_anchor}`;
const title = `HM gate — Step ${g.step} ${g.label} — show ${show}`;
const lines = [
  g.hm_ui_instruction,
  `HM UI location: ${link}`,
  `Resume form: ${resume}`,
  'Decision: Approve|Rework',
  `Notes: ${g.Notes || '{Notes}'}`,
  `show_id: ${show}`,
  `step: ${g.step}; step_id: ${g.step_id}; step_label: ${g.step_label}`,
  'Open HM UI, review/edit, then submit Approve or Rework in the n8n form to resume.',
];
return [{ json: { ...g, notify_title: title, notify_text: title + '\n' + lines.join('\n'), hm_ui_deep_link: link, resume_form_url: resume } }];

